		tgt.[apuk_customeridname] = stg.[apuk_customeridname],
		tgt.[apuk_customeridyominame] = stg.[apuk_customeridyominame],
		tgt.[apuk_description] = stg.[apuk_description],
		tgt.[apuk_escalationlevel] = stg.[apuk_escalationlevel],
		tgt.[apuk_name] = stg.[apuk_name],
		tgt.[apuk_origin] = stg.[apuk_origin],
		tgt.[apuk_regardingtype] = stg.[apuk_regardingtype],
		tgt.[apuk_regulatedfirm] = stg.[apuk_regulatedfirm],
