		tgt.[apuk_regulatedindividualname] = stg.[apuk_regulatedindividualname],
		tgt.[apuk_regulatedindividualyominame] = stg.[apuk_regulatedindividualyominame],
		tgt.[apuk_regulatedscheme] = stg.[apuk_regulatedscheme],
		tgt.[apuk_regulatedscheme_entitytype] = stg.[apuk_regulatedscheme_entitytype],
		tgt.[apuk_regulatedschemename] = stg.[apuk_regulatedschemename],
		tgt.[apuk_regulatorycontactid] = stg.[apuk_regulatorycontactid],
		tgt.[apuk_regulatorycontactid_entitytype] = stg.[apuk_regulatorycontactid_entitytype],
